            },
            "required": [
              "incomingItemId",
              "kind",
              "statement",
              "targetEntityId",
              "featureKey",
              "claimIds",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "operations"
      ]
    }
  },
  {
    "type": "function",
    "name": "save_state_change_plan",
    "description": "Speichert die finalen Operationen (genau eine je eingehendem Requirement). Genau einmal am Ende aufrufen.",
    "parameters": {
      "type": "object",
      "properties": {
        "operations": {
          "type": "array",
          "items": {
            "type": "object",
