    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "collect_clarify_katalog",
    "description": "C4-Zielschleife Schritt 1: die offenen Klaerungen (needs_clarify-PBIs) mit LUECKEN-DIAGNOSE (STATEMENT_FEHLT/AK_LEER/HISTORIE) \u002B REQ-Kontext \u2014 read-only, LLM-frei. Lies dem Autor je PBI die Luecke vor und sammle seine Antwort ein.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "get_core_overview",
    "description": "Read-only-Ueberblick der Projektwahrheit: Item-Zaehlung je Typ, offene Entscheidungen (Parkplatz), Relations-Anzahl und die Kangal-Integritaetslage (Fehler/Warnungen).",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "list_core_items",
    "description": "Listet Items der Projektwahrheit kompakt (id, typ, status, text gekuerzt). Filter: itemType (z. B. pbi|requirement|feature|decision|architecture), sourceRunId = nur Items aus diesem Lauf (Wahrheits-seitige Lauf-Bilanz), status = exakter Status-Wert (z. B. needs_clarify|active|accepted|open_decision|blocked_by_decision \u2014 fuer Status-Fragen DIESEN Filter nutzen statt Items einzeln zu oeffnen), query = genau EIN woertlicher Suchbegriff (Substring, case-insensitiv, Umlaut-tolerant; KEINE Operatoren wie OR \u2014 fuer Alternativen mehrfach aufrufen), includeSuperseded (Standard false = nur gueltige Wahrheit).",
    "parameters": {
      "type": "object",
      "properties": {
        "itemType": {
          "type": [
            "string",
            "null"
          ],
          "default": null
        },
        "status": {
          "type": [
            "string",
            "null"
          ],
          "default": null
        },
        "query": {
          "type": [
            "string",
            "null"
          ],
          "default": null
